SET LOCAL aidash.scope = 'deployment';
UPDATE "tasks" SET "started_by_duty" = COALESCE((SELECT "duty_ticks"."duty_id" FROM "duty_ticks" WHERE "duty_ticks"."tenant" = "tasks"."tenant" AND "duty_ticks"."task_id" = "tasks"."id" AND "duty_ticks"."started_by" IS NULL ORDER BY "duty_ticks"."recorded_at" DESC, "duty_ticks"."id" DESC LIMIT 1), CASE WHEN "duty_script" THEN "duty_id" END) WHERE ("tasks"."duty_script" = TRUE OR EXISTS (SELECT "duty_ticks"."duty_id" FROM "duty_ticks" WHERE "duty_ticks"."tenant" = "tasks"."tenant" AND "duty_ticks"."task_id" = "tasks"."id" AND "duty_ticks"."started_by" IS NULL ORDER BY "duty_ticks"."recorded_at" DESC, "duty_ticks"."id" DESC LIMIT 1));
UPDATE "events" SET "data" = jsonb_set("data", CASE WHEN jsonb_typeof("data" -> 'task') = 'object' THEN ARRAY['task', 'started_by_duty'] ELSE ARRAY['started_by_duty'] END, to_jsonb((SELECT "tasks"."started_by_duty" FROM "tasks" WHERE "tasks"."tenant" = "events"."tenant" AND "tasks"."started_by_duty" IS NOT NULL AND "tasks"."id" = CASE WHEN pg_input_is_valid(COALESCE("events"."data" #>> '{task,id}', "events"."data" ->> 'id'), 'uuid') THEN (COALESCE("events"."data" #>> '{task,id}', "events"."data" ->> 'id'))::uuid END))) WHERE "kind" IN ('task.created', 'task.claimed', 'task.updated', 'task.completed', 'task.abandoned') AND EXISTS (SELECT "tasks"."started_by_duty" FROM "tasks" WHERE "tasks"."tenant" = "events"."tenant" AND "tasks"."started_by_duty" IS NOT NULL AND "tasks"."id" = CASE WHEN pg_input_is_valid(COALESCE("events"."data" #>> '{task,id}', "events"."data" ->> 'id'), 'uuid') THEN (COALESCE("events"."data" #>> '{task,id}', "events"."data" ->> 'id'))::uuid END);
